// Vision coverage index — record JAH-GPC-AISECURITYCAM-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"res_mp": 8.3, "fov_deg": 110, "price_usd": 150};
var value = (m.res_mp*m.fov_deg/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-AISECURITYCAM-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-AISECURITYCAM-000001|' + value.toFixed(2) + ' coverage index');

